steps.action:
curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{
      projects(search: \"Checkout Redesign\") {
        nodes {
          id
          name
          docs(orderBy: updatedAt, first: 20) {
            nodes {
              id
              title
              updatedAt
              lastEditedById
            }
          }
        }
      }
      users(search: \"Leo Park\") {
        nodes {
          id
          name
        }
      }
    }"
  }'

curl -s -X POST https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{"query":"{ __type(name: \"Mutation\") { fields { name args { name type { name kind ofType { name } } } } } }"}' | python3 -c "
import json, sys
data = json.load(sys.stdin)
for f in data['data']['__type']['fields']:
    if f['name'] == 'documentUpdate':
        for a in f['args']:
            t = a['type']
            print(a['name'], t['kind'], t.get('name'), t.get('ofType',{}).get('name') if t.get('ofType') else None)
"
